CREATE TABLE accounts(id text PRIMARY KEY,username text UNIQUE NOT NULL,name text NOT NULL,role text NOT NULL,password text NOT NULL,disabled boolean NOT NULL DEFAULT false,simulated boolean NOT NULL DEFAULT false);
CREATE TABLE auth_sessions(token text PRIMARY KEY,user_id text NOT NULL REFERENCES accounts(id),expires bigint NOT NULL);
CREATE TABLE documents(collection text NOT NULL,id text NOT NULL,run_id text NOT NULL DEFAULT '',data jsonb NOT NULL,PRIMARY KEY(collection,id,run_id));
CREATE TABLE commands(scope text NOT NULL,key text NOT NULL,fingerprint text NOT NULL,result jsonb NOT NULL,PRIMARY KEY(scope,key));
CREATE TABLE journal(seq bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,run_id text NOT NULL,business_time text NOT NULL,kind text NOT NULL,actor_id text NOT NULL,payload jsonb NOT NULL);
CREATE INDEX journal_run_time ON journal(run_id,business_time,seq);
CREATE TABLE sessions(id text PRIMARY KEY,token_hash text UNIQUE,nickname text,run_id text,expires bigint);
CREATE TABLE conversations(id text PRIMARY KEY,owner text,run_id text,poi_id text,created_at text);
CREATE TABLE messages(id text PRIMARY KEY,conversation_id text,role text,text text,status text,sources jsonb,created_at text,error_code text,parent_id text,seq bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE INDEX message_conversation ON messages(conversation_id,seq);
CREATE TABLE attempts(scope text,request_key text,fingerprint text,message_id text,PRIMARY KEY(scope,request_key));
CREATE TABLE scenic_states(run_id text PRIMARY KEY,data jsonb NOT NULL);
CREATE TABLE data_migrations(id text PRIMARY KEY,completed_at timestamptz NOT NULL DEFAULT now(),report jsonb NOT NULL);
